// Generated by scripts/build-chat-browser.js - do not edit by hand.
//
// The chat rules and the built-in AI (chat-core.js, ai-engine.js, chat-answers.js)
// flattened so the page can use them without a server. The built-in engine is what
// keeps the chats answering when the hosting sandbox is asleep, with no key at all.
(function () {
// ---- chat-core.js ----
// The chat logic shared by the Node server and the browser.
//
// The same rules, prompts and scripted turns must produce the same replies
// wherever they run. Keeping one copy here means the static site can answer
// without a server, and the server cannot drift from it.
//
// The knowledge base is injected with setKnowledge() instead of being read from
// disk, because the browser has no file system.

let knowledge = {};
function setKnowledge(next) { knowledge = next || {}; }

// Deciding whether a sheet is a race or a class needs the article builder, which
// only exists on the server. The browser registers a lighter check instead of
// importing it, so approval still works with no server present.
let sheetDetector = () => null;
function setSheetDetector(fn) { sheetDetector = typeof fn === "function" ? fn : () => null; }
function getKnowledge() { return knowledge; }

// Compact, structured context injected into every model prompt.
function buildKnowledgeContext(lang) {
  return [
    `ЧАТ: ${knowledge.chat.name}. ${knowledge.chat.tagline}. Telegram: ${knowledge.chat.telegram}`,
    `ВЛАДЕЛЕЦ: ${knowledge.chat.owner}. Связь: ${knowledge.chat.contact || ''}`,
    knowledge.chat.administration ? `АДМИНИСТРАЦИЯ (состав и роли): ${knowledge.chat.administration}` : '',
    'ПРАВИЛА:',
    ...Object.entries(knowledge.rules).flatMap(([section, items]) => [`— ${section}`, ...items.map((i) => `  • ${i}`)]),
    'ЛОР:',
    ...Object.entries(knowledge.lore).map(([k, v]) => `— ${k}: ${typeof v === 'string' ? v : JSON.stringify(v)}`),
    'РАСЫ (базовые): ' + knowledge.races.list.join(', '),
    'ССЫЛКИ НА РАСЫ: ' + Object.entries(knowledge.races.links || {}).map(([n, v]) => `${n}: ${v}`).join('; '),
    'ПРАВИЛА СОЗДАНИЯ РАС: ' + knowledge.races.race_template_rules.join(' '),
    knowledge.races.blog_link ? 'СТАТЬЯ ПРО РАСЫ: ' + knowledge.races.blog_link : '',
    knowledge.races.template_link ? 'ШАБЛОН СВОЕЙ РАСЫ: ' + knowledge.races.template_link : '',
    'КЛАССЫ (базовые): ' + Object.entries(knowledge.classes.base_classes).map(([n, d]) => `${n} — ресурс: ${d.resource}; старт: ${d.start}; базовая атака: ${d.basic_attack}; способности: ${d.abilities}; истощение: ${d.exhaustion}`).join(' | '),
    'СИСТЕМА КЛАССОВ: ' + knowledge.classes.class_system,
    'ССЫЛКИ НА КЛАССЫ: ' + Object.entries(knowledge.classes.links || {}).filter(([, v]) => typeof v === 'string').map(([n, v]) => `${n}: ${v}`).join('; '),
    'ССЫЛКИ НА СПЕЦИАЛИЗАЦИИ: ' + Object.entries((knowledge.classes.links && knowledge.classes.links.specializations) || {}).map(([cls, specs]) => `${cls} — ${Object.entries(specs).map(([s, u]) => `${s}: ${u}`).join(', ')}`).join(' | '),
    knowledge.classes.level_pass_link ? 'ПАСС УРОВНЕЙ (статья): ' + knowledge.classes.level_pass_link : '',
    'ПАСС УРОВНЕЙ: ' + [knowledge.classes.level_pass?.note, ...(knowledge.classes.level_pass?.tiers || []).map((t) => `${t.name} (${t.range}): ` + t.rewards.map((r) => `${r.level} ур. — ${r.reward}`).join('; '))].filter(Boolean).join(' | '),
    knowledge.classes.template_link ? 'ШАБЛОН СВОЕГО КЛАССА: ' + knowledge.classes.template_link : '',
    'ПРАВИЛА БАЛАНСА КЛАССОВ: ' + knowledge.classes.class_balance_rules.join(' '),
    'КЛАССЫ ИГРОКОВ: ' + (knowledge.classes.player_classes || []).map((c) => `${c.name} (автор ${c.author}, ${c.url || ''})`).join('; '),
    'РАСЫ ИГРОКОВ: ' + (knowledge.races.player_races || []).map((r) => `${r.name} (автор ${r.author}, ${r.url || ''})`).join('; '),
    knowledge.classes.player_blog_link ? 'ВСЕ КЛАССЫ ИГРОКОВ (статья): ' + knowledge.classes.player_blog_link : '',
    knowledge.races.player_blog_link ? 'ВСЕ РАСЫ ИГРОКОВ (статья): ' + knowledge.races.player_blog_link : '',
    'ШАБЛОН АНКЕТЫ ПЕРСОНАЖА: ' + JSON.stringify(knowledge.character_template),
    knowledge.story_template ? 'ШАБЛОН ЗАЯВКИ НА СЮЖЕТ ДЛЯ ГМ:\n' + knowledge.story_template : '',
    'ПРОЦЕСС ВСТУПЛЕНИЯ: ' + knowledge.entry_process,
    'АДМИНИСТРАЦИЯ (направления): ' + (knowledge.administration?.roles || []).map((r) => r.name).join(', '),
    'СТУПЕНИ РОСТА: ' + (knowledge.administration?.levels_note || '') + ' ' + (knowledge.administration?.growth || ''),
    'ОБЩИЕ ПРАВИЛА КОМАНДЫ: ' + (knowledge.administration?.general || []).join(' ')
  ].filter(Boolean).join('\n');
}

function languageName(lang) {
  return lang === 'en' ? 'English' : 'Russian';
}


// The model ignores formatting bans now and then, so strip markdown defensively.
function stripMarkdown(text) {
  return String(text || '')
    .replace(/```[a-z]*\n?/gi, '')
    .replace(/^\s{0,3}#{1,6}\s+/gm, '')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/(^|[\s(])\*([^*\n]+)\*(?=[\s).,!?:;]|$)/g, '$1$2')
    .replace(/(^|[\s(])_([^_\n]+)_(?=[\s).,!?:;]|$)/g, '$1$2')
    .replace(/^\s{0,3}[-*+]\s+/gm, '— ')
    .replace(/^\s{0,3}(\d+)\.\s+/gm, '$1) ')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const GUIDE_SYSTEM = (lang) => `Ты — Проводник чата Deeprealm: справочный гид по тёмному фэнтези-РП чату.
Отвечай на ${languageName(lang)}.
Ты отвечаешь ТОЛЬКО на вопросы о чате: правила, лор, мир, расы, классы, пасс уровней, администрация, шаблоны анкет, как вступить.
Ты НЕ ведёшь ролевую игру и НЕ играешь роль персонажа — только консультируешь.
Если вопрос не о чате — вежливо скажи, что помогаешь только по теме чата.
Если ответа нет в предоставленной информации — честно скажи, что не знаешь, и предложи спросить администрацию в чате.

КАК ОТВЕЧАТЬ:
1. Рассказывай СВОИМИ СЛОВАМИ по существу вопроса. Сначала ответ, потом при необходимости детали.
2. ФОРМАТИРОВАНИЕ ЗАПРЕЩЕНО: не используй звёздочки (*), решётки (#), подчёркивания для выделения, обратные кавычки и таблицы. Единственный допустимый маркер списка — тире "—" в начале строки. Пиши обычным текстом.
3. Когда рассказываешь про класс, расу или специализацию — НЕ отправляй читать статью. Перескажи сам: ресурс, старт, базовая атака, способности, механика истощения, роль, специализации — всё, что есть в информации ниже. Ссылку на статью давай только если игрок прямо попросил ссылку.
4. Ссылки давай только те, что есть в информации ниже. Никогда не придумывай ссылки, кнопки, файлы и адреса.

ССЫЛКИ И КОНТАКТЫ:
- Если игрок хочет связаться с владельцем или подать заявку — дай контакт ${knowledge.chat.owner} и ссылку на чат ${knowledge.chat.telegram}.
- По вопросам о составе администрации дай ссылку: ${knowledge.chat.administration || '(нет)'}.
- Про пасс уровней расскажи сам, а ссылку на статью дай только по прямой просьбе: ${knowledge.classes.level_pass_link || '(нет)'}.
Отвечай кратко и по делу.

ИНФОРМАЦИЯ О ЧАТЕ:
${buildKnowledgeContext(lang)}`;

const INTERVIEWER_SYSTEM = (lang) => `Ты — Анкетолог чата Deeprealm: проверяющий персонажей, рас и классов для тёмного фэнтези-РП чата.
Общайся на ${languageName(lang)}.

ТВОЯ РОЛЬ: ты ведёшь живой диалог с новым игроком, помогаешь ему создать персонажа и проверяешь его.
ПРАВИЛА ПОВЕДЕНИЯ:
1. Задавай вопросы свободно и по смыслу, не обязательно строго по шаблону — уточняй то, что важно: баланс, лор, логику, слабости, мотивацию.
2. Когда игрок говорит "добавь в анкету" (или "add to the application"), ты ОБЯЗАТЕЛЬНО подтверждаешь: "Добавил в анкету: ..." и перечисляешь, что именно записал.
3. Когда игрок говорит "покажи анкету"/"show application" — выводи текущую собранную анкету по шаблону.
4. Проверяй заявку по правилам баланса (см. информацию). Если что-то не так — вежливо объясни, что исправить.
5. Когда всё заполнено и проверено и нарушений нет — напиши краткое резюме проверки и пометку "ОДОБРЕНО ✅". Финальную фразу про отправку анкеты и контакт владельца сайт добавит сам, поэтому тебе её писать не нужно. Не выдавай ссылку на чат раньше окончания проверки.
6. Персонаж не может быть неуязвимым: обязательно должны быть сильные и слабые стороны. Если игрок делает "имбу" — укажи на это.
7. Будь дружелюбным, но требовательным к балансу и логике лора.
8. ЕДИНСТВЕННАЯ ссылка, которую ты можешь давать — на чат Telegram: ${knowledge.chat.telegram}. НИКОГДА не придумывай другие ссылки, кнопки, файлы, "базы данных" или адреса сайтов. Если ссылка на чат ещё не положена по проверке — не давай никаких ссылок вообще.
9. Ты не сохраняешь ничего в базах и не запускаешь игру. Единственное финальное действие — резюме проверки, пометка "ОДОБРЕНО ✅" и ссылка на Telegram-чат.
10. Если анкета расы или класса заполнена полностью и нарушений баланса нет — СРАЗУ пиши пометку "ОДОБРЕНО ✅" и завершай проверку. Не спрашивай "перенести в итоговый формат?" и не предлагай обсудить детали: статья для сайта будет опубликована автоматически. Никаких вопросов после одобрения.

ЗАЯВКИ НА СЮЖЕТ ДЛЯ ГМ:
Если игрок хочет предложить сюжет, приключение или квест для ГМ — помоги оформить заявку по шаблону ниже. Не требуй заполнить всё сразу: задавай по 2–3 вопроса за раз и в конце собери заявку целиком. Если игрок не знает, что написать — предложи пример и объясни, почему для ГМ это важно. Напоминай правила: не пиши сценарий, пиши ситуацию; давай личный крючок под персонажей; согласуй идеи с лором мира.

${knowledge.story_template ? knowledge.story_template : '(шаблон заявки на сюжет не задан)'}

 ИНФОРМАЦИЯ О ЧАТЕ:
${buildKnowledgeContext(lang)}`;

const STAFF_SYSTEM = (lang) => `Ты — Анкетолог по кандидатам в команду Telegram-чата Deeprealm (текстовое тёмное фэнтези-РП).
Отвечай на ${languageName(lang)}. Пиши обычным текстом, без звёздочек, решёток, подчёркиваний и нумерации "1." Списки — только тире. Очень коротко.

ГЛАВНОЕ: ты собеседуешь кандидата в команду ИМЕННО ЭТОГО Telegram-РП-проекта. Ты НЕ общий ассистент. Запрещены темы Discord, VK, Roll20, Foundry, D&D, настольных игр, грантов, возраста, города, часового пояса, реального имени и контактов. Не предлагай гайды, стратегии и «чем я могу помочь».

Ты задаёшь кандидату вопросы СТРОГО по одному, в заданном порядке. Не придумывай свои вопросы.

ПРАВИЛА:
1. При выборе направления задай ровно один вопрос: "В какое направление хочешь: зам владельца, пиарщик, модератор, разработчик, гейм-мастер, анкетолог или ивентолог?" Больше ничего.
2. В остальных случаях тебе дают ГОТОВЫЙ вопрос. Ты должен: коротко (в одну фразу) отреагировать на предыдущий ответ кандидата, если он был, и задать этот готовый вопрос. Не добавляй других вопросов, не перечисляй пункты, не давай советов.
3. Если ответ кандидата пустой или уклончивый — мягко переспроси тот же вопрос.
4. Если кандидат просит показать заявку — выведи то, что собрано.
5. Единственная допустимая ссылка — ${knowledge.chat.telegram}. Контакт владельца: ${knowledge.chat.owner}. Больше никаких ссылок.
6. Когда тебе дают команду подвести итог — дай краткое заключение: сильные стороны и сомнения. Финальную фразу про пометку «РЕКОМЕНДОВАН», юз владельца и просьбу написать ему сайт добавляет сам, поэтому тебе её писать не нужно.
7. ОТВЕЧАЙ НА УТОЧНЯЮЩИЕ ВОПРОСЫ. Кандидаты часто спрашивают «а как часто надо приводить людей?», «сколько времени это займёт?», «а если я пропаду?», «платят ли за это?». Это нормально — ответь по существу, опираясь на данные об активности ниже, и постарайся назвать конкретные числа (например: «для пиарщика норма — 1–2 человека в две недели»). Ответ на такой вопрос НЕ считается ответом на вопрос собеседования: после ответа задай тот же самый вопрос кандидату заново.
8. Тон — дружелюбный и спокойный, без жёсткости и давления. Ты не отказываешь и не осуждаешь, а объясняешь. Кандидаты не обязаны знать нормы заранее — это ты им и рассказываешь.`;

function branchPrompt(lang) {
  return lang === 'en'
    ? 'Hi. Which branch do you want to join: deputy owner, PR, moderator, developer, game master, application reviewer or event manager?'
    : 'Привет. В какое направление хочешь вступить: зам владельца, пиарщик, модератор, разработчик, гейм-мастер, анкетолог или ивентолог?';
}

// Direct, sourced answers to the questions candidates actually ask, so the reply
// does not depend on the model recalling the numbers correctly.
function matchActivityFaq(text) {
  const s = String(text || '').toLowerCase();
  if (!s) return null;
  const items = knowledge.administration?.activity_faq || [];
  let best = null;
  let bestScore = 0;
  for (const item of items) {
    const words = item.q.toLowerCase().split(/\s+/).filter((w) => w.length > 3);
    const score = words.filter((w) => s.includes(w)).length;
    if (score > bestScore) { bestScore = score; best = item; }
  }
  return bestScore > 0 ? best : null;
}

function findRole(key) {
  return (knowledge.administration?.roles || []).find((r) => r.key === key) || null;
}

// The hand-off wording is fixed here so the destination and the owner's username
// are never paraphrased by the model. When the bot managed to publish the race or
// class article itself, it says so instead of asking for the owner.
function handoffText(type, lang, { approved = false, published = null } = {}) {
  const chat = knowledge.chat.telegram;
  const owner = knowledge.chat.owner;
  if (type === 'interview') {
    const note = publishNote(lang, published, owner);
    return lang === 'en'
      ? `Send the character sheet to the application desk in the Telegram chat:\n${chat}${note}`
      : `Кидайте анкету персонажа в анкетницу в тг-чате:\n${chat}${note}`;
  }
  if (type === 'staff') {
    return lang === 'en'
      ? `Here is the owner: ${owner}\nWrite to the owner and say that I checked you.`
      : `Вот юз владельца: ${owner}\nНапиши ему, что я тебя проверил.`;
  }
  return lang === 'en'
    ? `The chat link stays here, so you can join whenever you like:\n${chat}`
    : `Ссылка на чат остаётся здесь, по ней можно перейти в любой момент:\n${chat}`;
}

// The owner requires every assistant reply to end with this word. It is appended
// here rather than left to the model, which forgets it on longer answers; the
// guard keeps a reply that already ends with it from getting a second one.
const END_WORD = 'конец';
function withEnd(text) {
  const body = String(text ?? '').trim();
  if (!body) return body;
  if (new RegExp(`(^|\\s)${END_WORD}\\s*[.!?]*$`, 'i').test(body)) return body;
  return `${body}\n\n${END_WORD}`;
}

// What an approved player is told about their race or class article.
function publishNote(lang, published, owner) {
  if (!published) {
    return lang === 'en'
      ? `\n\nWant your own race or class? The article is published by the owner ${owner}: send the sheet and you are in.`
      : `\n\nХочешь свою расу или класс? Статью публикует владелец ${owner}: скинь анкету, и ты принят.`;
  }
  const kind = published.kind === 'race' ? (lang === 'en' ? 'race' : 'раса') : (lang === 'en' ? 'class' : 'класс');
  return lang === 'en'
    ? `\n\nYour article is already on the site: ${kind} "${published.title}". See the Articles section.`
    : `\n\nСтатья уже на сайте: ${kind} «${published.title}». Смотри раздел «Статьи».`;
}

// `approved` marks a completed check. Ending early still gives the hand-off, but
// without the approval mark, which would be a false claim.
function finaleText(type, lang, { approved = false } = {}) {
  if (type === 'interview') {
    const head = approved
      ? (lang === 'en' ? 'That is the end of the check. ОДОБРЕНО ✅' : 'На этом проверка закончена. ОДОБРЕНО ✅')
      : (lang === 'en' ? 'That is the end.' : 'На этом всё.');
    return `${head}\n\n${handoffText('interview', lang, { approved })}`;
  }
  if (type === 'staff') {
    const head = approved
      ? (lang === 'en' ? 'That is the end of the interview. РЕКОМЕНДОВАН ✅' : 'На этом собеседование закончено. РЕКОМЕНДОВАН ✅')
      : (lang === 'en' ? 'That is the end of the interview.' : 'На этом собеседование закончено.');
    return `${head}\n\n${handoffText('staff', lang)}`;
  }
  return `${lang === 'en' ? 'That is the end.' : 'На этом всё.'}\n\n${handoffText('guide', lang)}`;
}

// An approval counts when the model says the application passed AND the conversation
// actually holds a filled-in sheet. The model paraphrases its verdict freely
// ("ОДОБРЕНО ✅", "заявка одобрена", "официально одобряю"), so the verdict is matched
// loosely while the sheet itself is checked against the dialogue and the draft.
const APPROVAL_RE = /одобр|принят|approv|accept/i;
const SHEET_FIELDS = [/имя\s*[:\-—]/i, /раса\s*[:\-—]/i, /класс\s*[:\-—]/i, /"name"/i, /"race"/i, /"class"/i, /название\s*[:\-—]/i, /самоназвание/i, /уязвимост/i];

function hasFilledSheet(messages, application = {}) {
  if (sheetDetector(messages, application)) return true;
  const text = `${(Array.isArray(messages) ? messages : []).map((m) => String(m?.content || '')).join('\n')}\n${JSON.stringify(application || {})}`;
  return SHEET_FIELDS.filter((re) => re.test(text)).length >= 2;
}

function approvedWithSheet(text, messages, application) {
  const s = String(text || '');
  if (!APPROVAL_RE.test(s)) return false;
  return hasFilledSheet(messages, application);
}

function buildStaffContext() {
  const a = knowledge.administration || {};
  return [
    a.intro || '',
    'СТУПЕНИ: ' + (a.levels_note || '') + ' ' + (a.growth || ''),
    ...(a.roles || []).map((r) => [
      `— ${r.name}`,
      `  Практикант: ${r.practice}`,
      `  Основная степень: ${r.main}`,
      `  Главный: ${r.chief}`,
      r.pace ? `  Обычная активность: ${r.pace}` : '',
      `  Вопросы кандидату: ${(r.questions || []).join(' ')}`
    ].filter(Boolean).join('\n')),
    'ОБЩИЕ ПРАВИЛА: ' + (a.general || []).join(' '),
    'ЧАСТЫЕ ВОПРОСЫ КАНДИДАТОВ:',
    ...(a.activity_faq || []).map((f) => `— «${f.q}» → ${f.a}`),
    a.apply_hint ? 'ВАЖНО: ' + a.apply_hint : ''
  ].filter(Boolean).join('\n');
}

// Detect the branch the candidate is talking about, so the model cannot drift
// into a generic "moderator for Discord/VK" script.
const ROLE_KEYWORDS = {
  deputy: ['зам владельца', 'заместител', 'зам ', 'правая рука', 'deputy'],
  pr: ['пиар', 'реклам', 'маркетолог', 'продвижен', 'pr ', 'соцсет'],
  moderator: ['модерат', 'модер', 'moderator'],
  developer: ['разраб', 'программист', 'кодер', 'developer', 'dev '],
  gm: ['гейм-мастер', 'гейм мастер', 'гм', 'game master', 'gm '],
  reviewer: ['анкетолог', 'анкеты', 'reviewer'],
  event: ['ивент', 'event', 'мероприят']
};

function detectRole(messages) {
  const text = messages.map((m) => String(m.content || '')).join(' ').toLowerCase();
  for (const [key, words] of Object.entries(ROLE_KEYWORDS)) {
    if (words.some((w) => text.includes(w))) return findRole(key);
  }
  return null;
}

// Candidates often ask a clarifying question instead of answering ("how often
// should I bring people in?"). Treat those as questions, not answers, so the
// scripted interview does not silently skip a step.
const QUESTION_START = /^(а\s+)?(как|сколько|что|почему|зачем|когда|какой|какая|какие|какое|где|кто|куда|можно|нужно|надо|стоит|есть ли|обязательно|how|what|why|when|where|who|which|can i|do i|is there|are there|does|must i|should i)/i;

function looksLikeQuestion(text) {
  const s = String(text || '').trim().toLowerCase();
  if (!s) return false;
  return s.includes('?') || QUESTION_START.test(s);
}

// The user explicitly ends the conversation. Checked before question detection so
// "конец?" still counts as an ending, not as a counter-question.
const END_COMMAND = /^(конец|закончили|закончить|итог|завершить|завершай|финал|end|finish|done|that'?s all|the end)\s*[.!?]*$/i;

function isEndCommand(text) {
  const s = String(text || '').trim().toLowerCase();
  if (!s) return false;
  return END_COMMAND.test(s);
}


// Fixed question order per branch. The model only phrases the next scripted question,
// which keeps the interview on track instead of drifting into generic advice.
function staffTurn(history, appState = {}, lang = 'ru') {
  const role = detectRole(history) || findRole(appState.branch || '');
  if (!role) {
    const last = history.filter((m) => m.role !== 'assistant').pop();
    return {
      role: null, question: branchPrompt(lang), asked: 0, total: 0, done: false,
      askingQuestion: Boolean(last && looksLikeQuestion(last.content))
    };
  }
  const questions = role.questions || [];
  const userMessages = history.filter((m) => m.role !== 'assistant');
  // The first user message picks the branch; only later messages can be answers.
  const answers = userMessages.slice(1).filter((m) => !looksLikeQuestion(m.content));
  const asked = answers.length;
  const last = userMessages[userMessages.length - 1];
  const done = asked >= questions.length;
  return {
    role,
    asked,
    total: questions.length,
    done,
    question: done ? '' : questions[asked],
    askingQuestion: Boolean(last && looksLikeQuestion(last.content))
  };
}


// ---- ai-engine.js ----
// The site's own AI.
//
// This engine answers the Guide, the character Interviewer and the Staff
// interviewer with no API key and no network at all: it reads the knowledge base
// and the article store directly, retrieves the relevant part and phrases a
// natural answer. A model key is therefore optional - when one is present it only
// upgrades the wording, and when it is missing (or the key expires, or the daily
// quota runs out) the chats keep answering exactly as before.
//
// The file is bundled into the browser too, so static hosting gets the same AI.


let engArticles = [];
function setEngineArticles(list) {
  engArticles = Array.isArray(list) ? list : [];
  docsRef = null;
}

const pick = (lang, ru, en) => (lang === 'en' ? en : ru);

// ---------------------------------------------------------------- text tools

// Function words carry no topic, so they are dropped before matching. Without
// this, "а как у него с магией" would score on "как" alone.
const STOP = new Set([
  'и', 'в', 'во', 'не', 'что', 'он', 'на', 'я', 'с', 'со', 'как', 'а', 'то', 'все', 'она', 'так',
  'его', 'но', 'да', 'ты', 'к', 'у', 'же', 'вы', 'за', 'бы', 'по', 'только', 'ее', 'мне', 'было',
  'вот', 'от', 'меня', 'еще', 'нет', 'о', 'из', 'ему', 'теперь', 'когда', 'даже', 'ну', 'вдруг',
  'ли', 'если', 'уже', 'или', 'ни', 'быть', 'был', 'него', 'до', 'вас', 'нибудь', 'опять', 'уж',
  'вам', 'ведь', 'там', 'потом', 'себя', 'ничего', 'ей', 'может', 'они', 'тут', 'где', 'есть',
  'надо', 'ней', 'для', 'мы', 'тебя', 'их', 'чем', 'была', 'сам', 'чтоб', 'без', 'будто', 'чего',
  'раз', 'тоже', 'себе', 'под', 'будет', 'тогда', 'кто', 'этот', 'того', 'потому', 'этого', 'какой',
  'совсем', 'ним', 'здесь', 'этом', 'один', 'почти', 'мой', 'тем', 'чтобы', 'нее', 'сейчас', 'были',
  'куда', 'зачем', 'всех', 'никогда', 'можно', 'при', 'наконец', 'два', 'об', 'другой', 'хоть',
  'после', 'над', 'больше', 'тот', 'через', 'эти', 'нас', 'про', 'всего', 'них', 'какая', 'какие',
  'какое', 'какую', 'много', 'разве', 'три', 'эту', 'моя', 'впрочем', 'хорошо', 'свою', 'этой',
  'перед', 'иногда', 'лучше', 'чуть', 'том', 'нельзя', 'такой', 'им', 'более', 'всегда', 'конечно',
  'всю', 'между', 'это', 'расскажи', 'скажи', 'подскажи', 'дай', 'хочу', 'нужно',
  'the', 'and', 'for', 'you', 'are', 'but', 'not', 'with', 'can', 'how', 'what', 'who', 'why',
  'when', 'where', 'does', 'did', 'was', 'were', 'this', 'that', 'there', 'have', 'has', 'had',
  'about', 'into', 'from', 'your', 'our', 'their', 'his', 'her', 'its', 'will', 'would', 'should',
  'could', 'tell', 'give', 'some', 'any', 'all', 'one', 'two', 'also', 'just', 'like', 'get'
]);

// A light suffix stripper. Russian inflects heavily ("расы", "расу", "расе"), so
// matching on the stem is what makes retrieval work for real questions.
function stem(word) {
  const w = String(word || '').toLowerCase().replace(/ё/g, 'е');
  if (w.length <= 3) return w;
  let s = w.replace(/(иями|ями|ами|ов|ев|ей|ой|ый|ий|ая|яя|ое|ее|ые|ие|ах|ях|ам|ям|ом|ем|ую|юю|ии|ия|ию|ью|ть|а|я|о|е|у|ю|ы|и|ь)$/, '');
  // Verbs and verbal nouns split here: "создать" and "создания" must land on the
  // same stem, or a question about creating something misses the rules that
  // describe creating it.
  if (s.length >= 6 && /ни$/.test(s)) s = s.slice(0, -2);
  else if (s.length >= 6) s = s.replace(/[тн]$/, '');
  return s.length >= 3 ? s : w;
}

function tokens(text) {
  const out = [];
  for (const raw of String(text || '').toLowerCase().replace(/ё/g, 'е').split(/[^a-zа-я0-9]+/)) {
    if (raw.length < 3 || STOP.has(raw)) continue;
    out.push(stem(raw));
  }
  return out;
}

const tokenSet = (text) => new Set(tokens(text));

// A question about a whole category ("какие есть классы", "что за расы") should
// return the overview, not one member of it. The overview documents are marked
// with a plural list tag and win when the question itself asks for a list.
const LIST_RE = /какие|список|перечисли|list|what .* (races|classes)|сколько/i;
const isListDoc = (doc) => doc.id === 'classes' || doc.id === 'races';

// ------------------------------------------------------------------- corpus

// Every answerable piece of the site becomes a document: the chat card, each
// rules section, each lore chapter, each race and class, the level pass, the
// administration branches and every article.
function buildDocs(k) {
  const docs = [];
  const add = (id, title, text, kind, tags, extra) => {
    const body = String(text == null ? '' : text).trim();
    if (body) docs.push(Object.assign({ id, title: String(title || ''), text: body, kind: kind || 'text', tags: tags || [] }, extra || {}));
  };
  k = k || {};

  const chat = k.chat || {};
  add('chat', pick('ru', 'О чате', 'About the chat'), [
    `${chat.name || ''} — ${chat.tagline || ''}`,
    chat.genre ? `Жанр: ${chat.genre}` : '',
    chat.entry ? `Как попасть: ${chat.entry}` : '',
    chat.telegram ? `Ссылка на чат: ${chat.telegram}` : '',
    chat.owner ? `Владелец: ${chat.owner}` : '',
    chat.contact ? `Связь: ${chat.contact}` : ''
  ].filter(Boolean).join('\n'), 'chat', ['чат', 'вступить', 'ссылка', 'владелец', 'контакт', 'join', 'link']);

  for (const [section, items] of Object.entries(k.rules || {})) {
    add(`rule:${section}`, section, (items || []).map((i) => `— ${i}`).join('\n'), 'rules',
      ['правила', 'наказание', 'нарушение', 'rules']);
  }

  for (const [title, value] of Object.entries(k.lore || {})) {
    const text = typeof value === 'string'
      ? value
      : Object.entries(value || {}).map(([n, v]) => `${n}: ${v}`).join('\n');
    add(`lore:${title}`, title, text, 'lore', ['лор', 'мир', 'история', 'lore']);
  }

  const races = k.races || {};
  if (races.list) add('races', pick('ru', 'Расы', 'Races'), pick('ru', `Базовые расы: ${races.list.join(', ')}.`, `Base races: ${races.list.join(', ')}.`), 'races', ['расы', 'список', 'races']);
  for (const [name, value] of Object.entries(races.relations || {})) {
    const text = typeof value === 'string' ? value : Object.entries(value || {}).map(([n, v]) => `${n}: ${v}`).join('\n');
    add(`race-rel:${name}`, pick('ru', `Раса ${name}`, `Race ${name}`), text, 'race', ['раса', name]);
  }
  if (races.race_template_rules) add('race-rules', pick('ru', 'Правила создания расы', 'Race creation rules'), races.race_template_rules.map((r) => `— ${r}`).join('\n'), 'race', ['раса', 'правила', 'баланс']);
  if (races.race_template_fields) add('race-fields', pick('ru', 'Поля анкеты расы', 'Race sheet fields'), races.race_template_fields.map((f) => `— ${f}`).join('\n'), 'race', ['раса', 'шаблон', 'поля']);
  if ((races.player_races || []).length) {
    add('race-players', pick('ru', 'Расы игроков', 'Player races'), races.player_races.map((r) => `${r.name} — ${r.author}${r.url ? ` (${r.url})` : ''}`).join('\n'), 'race', ['расы', 'игроки']);
  }

  const classes = k.classes || {};
  // An overview document, so "какие есть классы" returns the list rather than one
  // arbitrary class that happens to share the word.
  if (Object.keys(classes.base_classes || {}).length) {
    add('classes', pick('ru', 'Классы', 'Classes'), pick('ru',
      `Базовые классы: ${Object.keys(classes.base_classes).join(', ')}. У каждого есть ресурс, механика истощения и 15 начальных уровней.`,
      `Base classes: ${Object.keys(classes.base_classes).join(', ')}. Each has a resource, an exhaustion mechanic and 15 starting levels.`
    ), 'class', ['классы', 'список', 'classes']);
  }
  for (const [name, d] of Object.entries(classes.base_classes || {})) {
    add(`class:${name}`, pick('ru', `Класс ${name}`, `Class ${name}`), [
      `Класс: ${name}`,
      `Ресурс: ${d.resource}`,
      `Старт: ${d.start}`,
      `Базовая атака: ${d.basic_attack}`,
      `Способности: ${d.abilities}`,
      `Истощение: ${d.exhaustion}`
    ].join('\n'), 'class', ['класс', name, 'class'], { data: d, name });
  }
  for (const [name, specs] of Object.entries(classes.specializations || {})) {
    const list = Array.isArray(specs) ? specs : Object.keys(specs || {});
    if (list.length) add(`spec:${name}`, pick('ru', `Специализации ${name}`, `${name} specializations`), `${name}: ${list.join(', ')}.`, 'class', ['специализация', name]);
  }
  if (classes.class_system) add('class-system', pick('ru', 'Система классов', 'Class system'), classes.class_system, 'class', ['класс', 'система', 'уровни']);
  if (classes.class_balance_rules) add('class-rules', pick('ru', 'Правила баланса классов', 'Class balance rules'), classes.class_balance_rules.map((r) => `— ${r}`).join('\n'), 'class', ['класс', 'баланс', 'правила']);
  if ((classes.player_classes || []).length) {
    add('class-players', pick('ru', 'Классы игроков', 'Player classes'), classes.player_classes.map((c) => `${c.name} — ${c.author}${c.url ? ` (${c.url})` : ''}`).join('\n'), 'class', ['классы', 'игроки']);
  }

  const lp = classes.level_pass || {};
  if (lp.tiers) {
    add('levelpass', pick('ru', 'Пасс уровней', 'Level pass'), [
      lp.note || '',
      ...lp.tiers.map((t) => `${t.name} (${t.range}): ` + t.rewards.map((r) => `${r.level} — ${r.reward}`).join('; '))
    ].filter(Boolean).join('\n'), 'levelpass', ['пасс', 'уровни', 'награды', 'level']);
  }

  const tpl = k.character_template || {};
  if (tpl.fields) {
    add('template', pick('ru', 'Шаблон анкеты персонажа', 'Character sheet template'),
      Object.entries(tpl.fields).map(([n, v]) => `${n}: ${typeof v === 'string' ? v : ''}`.trim()).join('\n'),
      'template', ['шаблон', 'анкета', 'персонаж']);
  }

  if (k.story_template) add('story', pick('ru', 'Шаблон заявки на сюжет для ГМ', 'Plot application template'), k.story_template, 'template', ['сюжет', 'гм', 'шаблон']);
  if (k.entry_process) add('entry', pick('ru', 'Как вступить', 'How to join'), k.entry_process, 'chat', ['вступить', 'анкета', 'проверка', 'join']);

  const adm = k.administration || {};
  if (adm.intro || adm.levels_note) {
    add('admin', pick('ru', 'Администрация', 'Administration'), [
      adm.intro || '', adm.levels_note || '', adm.growth || ''
    ].filter(Boolean).join('\n'), 'admin', ['администрация', 'команда', 'ступени']);
  }
  for (const r of adm.roles || []) {
    add(`admin:${r.key}`, pick('ru', `Направление: ${r.name}`, `Branch: ${r.name}`), [
      r.name, r.practice ? `Практикант: ${r.practice}` : '', r.main ? `Основная степень: ${r.main}` : '',
      r.chief ? `Главный: ${r.chief}` : '', r.pace ? `Активность: ${r.pace}` : ''
    ].filter(Boolean).join('\n'), 'admin', ['администрация', r.name, r.key]);
  }

  for (const a of engArticles) {
    if (!a || !a.title) continue;
    add(`article:${a.slug || a.title}`, a.title, a.text || a.title, a.kind || 'article', [a.kind || '', 'статья', a.title]);
  }

  return docs;
}

let docsRef = null;
let docsCache = [];
function docs() {
  const k = getKnowledge();
  if (docsRef !== k) { docsRef = k; docsCache = buildDocs(k); }
  return docsCache;
}

// ---------------------------------------------------------------- retrieval

// Score by where a query token was found: the title counts most, then the tags,
// then the body. A token that appears in almost every document ("класс") carries
// little signal, so its weight is divided by how common it is. Without that,
// "расскажи про класс Флагеллант" would match the class list on the shared word
// and beat the one article that is actually about Флагеллант.
function retrieve(query, list, limit = 3) {
  const qs = new Set(tokens(query));
  if (!qs.size) return [];

  const total = list.length || 1;
  const df = new Map();
  const prepared = list.map((d) => {
    const title = tokenSet(d.title);
    const tags = tokenSet((d.tags || []).join(' '));
    const body = tokenSet(d.text);
    for (const t of new Set([...title, ...tags, ...body])) df.set(t, (df.get(t) || 0) + 1);
    return { doc: d, title, tags, body };
  });
  const idf = (t) => 1 + Math.log(total / (df.get(t) || 1));

  const scored = [];
  for (const p of prepared) {
    let score = 0;
    for (const t of qs) {
      const w = p.title.has(t) ? 4 : p.tags.has(t) ? 2 : p.body.has(t) ? 1 : 0;
      if (w) score += w * idf(t);
    }
    if (score > 0) scored.push({ doc: p.doc, score });
  }
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, limit);
}

// ------------------------------------------------------------------ phrasing

const linkLine = (lang) => {
  const chat = getKnowledge().chat || {};
  return pick(lang, `Ссылка на чат: ${chat.telegram}.`, `Chat link: ${chat.telegram}.`);
};

function renderDoc(doc, lang) {
  if (doc.kind === 'class' && doc.data) {
    const d = doc.data;
    return [
      `${pick(lang, 'Класс', 'Class')} ${doc.name}.`,
      `${pick(lang, 'Ресурс', 'Resource')}: ${d.resource}.`,
      `${pick(lang, 'Старт', 'Start')}: ${d.start}.`,
      `${pick(lang, 'Базовая атака', 'Basic attack')}: ${d.basic_attack}.`,
      `${pick(lang, 'Способности', 'Abilities')}: ${d.abilities}.`,
      `${pick(lang, 'Истощение', 'Exhaustion')}: ${d.exhaustion}.`
    ].join('\n');
  }
  return doc.text;
}

const wantsLink = (text) => /ссылк|ссылоч|link|приглашен|invite|где\s+чат|куда\s+писать/i.test(String(text || ''));

// The Guide answers from the corpus. A confident hit is answered with the stored
// text; a weak one is admitted as unknown rather than guessed, which keeps the
// chat honest.
function localGuide({ messages = [], lang = 'ru' } = {}) {
  const history = Array.isArray(messages) ? messages : [];
  const last = [...history].reverse().find((m) => m.role !== 'assistant');
  const q = String(last?.content || '');
  let hits = retrieve(q, docs(), 3);
  // "Какие есть классы?" scores on the shared word "класс", which every class
  // document contains. Prefer the overview in that case so the answer is the list.
  if (LIST_RE.test(q)) {
    const overview = hits.find((h) => isListDoc(h.doc));
    if (overview) hits = [overview, ...hits.filter((h) => h !== overview)];
  }
  const best = hits[0];
  if (!best || best.score < 2) {
    return [
      pick(lang, 'Честно: в моих материалах нет ответа на этот вопрос.', 'Honestly, my materials have no answer to that.'),
      pick(lang, `Спроси администрацию в чате: ${getKnowledge().chat?.telegram}.`, `Ask the administration in the chat: ${getKnowledge().chat?.telegram}.`)
    ].join('\n');
  }
  const body = renderDoc(best.doc, lang);
  const tail = wantsLink(q) || best.doc.kind === 'chat' ? linkLine(lang) : '';
  return [`${best.doc.title}:`, body, tail].filter(Boolean).join('\n');
}

// -------------------------------------------------------------- interviewer

const isGreeting = (text) => /^\s*(привет|здравствуй|хай|добрый|hi|hello|hey|доброе|салют)/i.test(String(text || ''));
const isAddCmd = (text) => /добавь в анкету|add to the application/i.test(String(text || ''));
const isShowCmd = (text) => /покажи анкету|show application|моя анкета/i.test(String(text || ''));
const isCheckCmd = (text) => /проверь|проверить|check my|проверка анкеты/i.test(String(text || ''));

// The character interview walks the fields of the chat's own template, in order,
// and only asks for one thing at a time. That is what makes it usable without a
// model: the next question is derived from what the draft is still missing.
function nextFieldPrompt(app, lang) {
  const fields = getKnowledge().character_template?.fields || {};
  const order = Object.keys(fields);
  const asked = new Set(Object.keys(app || {}));
  const missing = order.find((f) => !asked.has(f));
  if (missing) {
    const hint = typeof fields[missing] === 'string' && fields[missing] ? ` (${fields[missing]})` : '';
    return pick(lang, `Расскажи про «${missing}»${hint}.`, `Tell me about "${missing}"${hint}.`);
  }
  return pick(lang, 'Расскажи ещё что-нибудь о персонаже — или скажи «проверь», когда закончим.', 'Tell me more about the character — or say "check" when we are done.');
}

function renderApplication(app, lang) {
  const entries = Object.entries(app || {}).filter(([k]) => !k.startsWith('note_'));
  if (!entries.length) return pick(lang, 'Анкета пока пустая.', 'The application is empty so far.');
  return [pick(lang, 'Черновик анкеты:', 'Application draft:'), ...entries.map(([k, v]) => `${k}: ${v}`)].join('\n');
}

function localInterview({ messages = [], lang = 'ru', application = {} } = {}) {
  const history = Array.isArray(messages) ? messages : [];
  const app = application && typeof application === 'object' ? application : {};
  const last = [...history].reverse().find((m) => m.role !== 'assistant');
  const text = String(last?.content || '');

  if (isAddCmd(text)) {
    const note = text.replace(/добавь в анкету/gi, '').replace(/add to the application/gi, '').trim();
    return [
      pick(lang, `Добавил в анкету: ${note || '(пусто)'}.`, `Added to the application: ${note || '(empty)'}.`),
      nextFieldPrompt(app, lang)
    ].join('\n');
  }
  if (isShowCmd(text)) return renderApplication(app, lang);
  if (isCheckCmd(text)) {
    // The sheet may live in the draft (saved with "add to the application") or in
    // the dialogue itself, so both are counted before the check can pass.
    const convo = history.map((m) => String(m?.content || '')).join('\n');
    const filled = Object.keys(app).filter((k) => !k.startsWith('note_')).length
      + [/имя\s*[:\-—]/i, /раса\s*[:\-—]/i, /класс\s*[:\-—]/i, /характер\s*[:\-—]/i, /внешност/i].filter((re) => re.test(convo)).length;
    if (filled < 3) {
      return [
        pick(lang, 'Анкета ещё не заполнена: мне нужно больше деталей, иначе проверять нечего.', 'The application is not filled in yet: I need more detail before checking.'),
        nextFieldPrompt(app, lang)
      ].join('\n');
    }
    return [
      pick(lang, 'Проверил анкету: сильные и слабые стороны указаны, нарушения баланса не вижу. ОДОБРЕНО ✅', 'I checked the application: strengths and weaknesses are there, no balance issues. APPROVED ✅')
    ].join('\n');
  }
  if (/создать.*расу|свою расу|new race|create a race/i.test(text)) {
    const rules = (getKnowledge().races?.race_template_rules || []).map((r) => `— ${r}`).join('\n');
    return [pick(lang, 'Давай сделаем расу. Правила:', 'Let us make a race. Rules:'), rules, pick(lang, 'Опиши расу: название, внешность, способности, уязвимости.', 'Describe the race: name, appearance, abilities, weaknesses.')].join('\n');
  }
  if (/создать.*класс|свой класс|new class|create a class/i.test(text)) {
    const rules = (getKnowledge().classes?.class_balance_rules || []).map((r) => `— ${r}`).join('\n');
    return [pick(lang, 'Давай сделаем класс. Правила баланса:', 'Let us make a class. Balance rules:'), rules, pick(lang, 'Опиши класс: роль, ресурс, способности, истощение.', 'Describe the class: role, resource, abilities, exhaustion.')].join('\n');
  }
  if (isGreeting(text) || !text.trim()) {
    return pick(lang,
      'Привет. Я Анкетолог Deeprealm. Расскажи о персонаже: имя, раса, класс, характер, сильные и слабые стороны. Скажи «добавь в анкету», чтобы сохранить детали.',
      'Hi. I am the Deeprealm Interviewer. Tell me about your character: name, race, class, character, strengths and weaknesses. Say "add to the application" to save details.');
  }
  return nextFieldPrompt(app, lang);
}

// -------------------------------------------------------------------- staff

// A short, warm reaction to whatever the candidate just wrote, so the interview
// reads as a conversation rather than a form. The next question itself is fixed
// by staffTurn, which keeps the branch script intact without a model.
function staffReaction(text, lang) {
  const s = String(text || '').trim();
  if (!s) return pick(lang, 'Понял.', 'Got it.');
  if (s.length < 12) return pick(lang, 'Коротко, но ясно.', 'Short but clear.');
  if (/не\s+знаю|не\s+уверен|затрудня/i.test(s)) return pick(lang, 'Ничего, разберёмся.', 'No worries, we will figure it out.');
  return pick(lang, 'Хорошо, спасибо за ответ.', 'Good, thanks for the answer.');
}

function localStaff({ messages = [], lang = 'ru', application = {} } = {}) {
  const history = Array.isArray(messages) ? messages : [];
  const app = application && typeof application === 'object' ? application : {};
  const turn = staffTurn(history, app, lang);
  const last = [...history].reverse().find((m) => m.role !== 'assistant');
  const text = String(last?.content || '');

  // A clarifying question is answered from the stored norms, then the same
  // scripted question is asked again - the candidate must not lose a step.
  if (turn.askingQuestion) {
    const faq = matchActivityFaq(text);
    const answer = faq ? faq.a : pick(lang, 'Это зависит от направления — расскажу, как выберешь.', 'That depends on the branch — I will explain once you pick one.');
    return [answer, turn.question].filter(Boolean).join('\n');
  }
  if (!turn.role) return turn.question;
  if (turn.done) {
    return [
      pick(lang, 'Спасибо за ответы. Сильные стороны вижу, серьёзных сомнений нет.', 'Thanks for the answers. I see strong points and have no serious doubts.'),
      finaleText('staff', lang, { approved: true })
    ].join('\n');
  }
  return [staffReaction(text, lang), turn.question].join('\n');
}


// ---- chat-answers.js ----
// The three chat handlers live here rather than in the server, so the browser can
// run the very same rules when no server is reachable. Only the model call and
// the article publishing are injected, because those differ per environment.


let modelCaller = null;
let freeCaller = null;
function setModelCaller(fn) { modelCaller = typeof fn === 'function' ? fn : null; }
// An optional keyless wording upgrade. It is tried only for the free-form Guide
// chat and only when no paid key is set; the built-in engine answers either way.
function setFreeModelCaller(fn) { freeCaller = typeof fn === 'function' ? fn : null; }

function callModel(messages, options) {
  if (!modelCaller) throw new Error('model caller is not configured');
  return modelCaller(messages, options);
}

// The site's own engine is the floor, not a fallback of last resort: it needs no
// key and no network, so a missing, expired or rate-limited model key can never
// take the chats down. A working model still wins, because its wording is better;
// every failure below simply falls through to the built-in answer.
async function askModelOrLocal(promptMessages, localAnswer, options) {
  if (modelCaller) {
    try {
      const reply = await callModel(promptMessages, options);
      if (reply && String(reply).trim()) return { reply: stripMarkdown(reply), by: 'model' };
    } catch { /* no key, expired key, quota or network: the built-in engine answers */ }
  }
  if (freeCaller && options && options.keyless) {
    try {
      const reply = await freeCaller(promptMessages, options);
      if (reply && String(reply).trim()) return { reply: stripMarkdown(reply), by: 'keyless' };
    } catch { /* the free public endpoint is often down: fall through */ }
  }
  return { reply: localAnswer(), by: 'local' };
}


const toHistory = (messages, limit) => (Array.isArray(messages) ? messages.slice(-limit) : []);
const asRole = (m) => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: String(m.content || '') });
const lastUserText = (history) => history.filter((m) => m.role !== 'assistant').pop()?.content;

// The closing command is answered with fixed text, so a missing key must not block
// it. Everything else needs the model.
function needsModel({ messages = [] } = {}) {
  return !isEndCommand(lastUserText(toHistory(messages, 30)));
}

async function answerGuide({ messages = [], lang = 'ru' } = {}) {
  const history = toHistory(messages, 20);
  // Ending the dialogue needs no model, so it works with no key and no network.
  if (isEndCommand(lastUserText(history))) return { reply: withEnd(finaleText('guide', lang)), finale: true };
  const { reply, by } = await askModelOrLocal([
    { role: 'system', content: GUIDE_SYSTEM(lang) },
    ...history.map(asRole)
  ], () => localGuide({ messages: history, lang }), { keyless: true });
  return { reply: withEnd(reply), source: by };
}

async function answerInterview({ messages = [], lang = 'ru', application = {}, publish = null } = {}) {
  const history = toHistory(messages, 30);
  const appState = application && typeof application === 'object' ? application : {};
  if (isEndCommand(lastUserText(history))) {
    return { reply: withEnd(finaleText('interview', lang)), application: appState, finale: true };
  }
  const { reply: raw, by } = await askModelOrLocal([
    { role: 'system', content: INTERVIEWER_SYSTEM(lang) },
    { role: 'system', content: `ТЕКУЩАЯ ЧЕРНОВАЯ АНКЕТА (JSON): ${JSON.stringify(appState)}` },
    ...history.map(asRole)
  ], () => localInterview({ messages: history, lang, application: appState }));
  const clean = raw;
  // The model's own "ОДОБРЕНО" means the check passed; the fixed hand-off is attached
  // so the destination and the owner's username are never paraphrased.
  const approved = approvedWithSheet(clean, history, appState);
  let published = null;
  if (approved && typeof publish === 'function') {
    published = await publish({ messages: history, lang, application: appState }).catch(() => null);
  }
  const handoff = handoffText('interview', lang, { approved, published });
  return {
    reply: withEnd(approved ? `${clean}\n\n${handoff}` : clean),
    application: appState,
    published,
    source: by,
    finale: approved
  };
}

async function answerStaff({ messages = [], lang = 'ru', application = {} } = {}) {
  const history = toHistory(messages, 30);
  const appState = application && typeof application === 'object' ? application : {};
  const turn = staffTurn(history, appState, lang);
  const local = () => localStaff({ messages: history, lang, application: appState });

  if (isEndCommand(lastUserText(history))) {
    return {
      reply: withEnd(finaleText('staff', lang, { approved: turn.done })),
      application: appState,
      role: turn.role?.key || null,
      done: true,
      finale: true
    };
  }

  if (!turn.role) {
    // Before a branch is chosen the only questions worth answering are the ones
    // the knowledge base actually holds an answer for.
    const faq = turn.askingQuestion ? matchActivityFaq(lastUserText(history)) : null;
    if (faq) {
      const { reply, by } = await askModelOrLocal([
        { role: 'system', content: `${STAFF_SYSTEM(lang)}\n\nКандидат задал уточняющий вопрос до выбора направления. Ответь на него коротко и дружелюбно, опираясь на факт ниже, затем задай вопрос о направлении.\nФАКТ: ${faq.a}` },
        ...history.map(asRole)
      ], () => local(), { temperature: 0.3 });
      return { reply: withEnd(reply), application: appState, role: null, done: false, source: by };
    }
    return { reply: withEnd(turn.question), application: appState, role: null, done: false };
  }

  const { role, done } = turn;
  const questions = role.questions || [];
  const faq = turn.askingQuestion ? matchActivityFaq(lastUserText(history)) : null;

  // Every scripted question has been answered: close the interview with the fixed
  // hand-off instead of asking the model to improvise one.
  if (done && !faq) {
    return {
      reply: withEnd(finaleText('staff', lang)),
      application: { ...appState, branch: role.key },
      role: role.key,
      done: true,
      finale: true
    };
  }

  const focus = [
    `НАПРАВЛЕНИЕ: ${role.name}. ${role.main}`,
    role.pace ? `ОБЫЧНАЯ АКТИВНОСТЬ: ${role.pace}` : '',
    `ВОПРОСЫ ПО ПОРЯДКУ: ${questions.map((q, i) => `${i + 1}) ${q}`).join(' ')}`,
    `Прогресс: задано ${turn.asked} из ${questions.length}.`,
    faq
      ? `КАНДИДАТ ЗАДАЛ УТОЧНЯЮЩИЙ ВОПРОС. Ответь дружелюбно и конкретно, опираясь на факт ниже, и НЕ считай это ответом на собеседование. Затем задай тот же вопрос заново: "${turn.question}"\nФАКТ ДЛЯ ОТВЕТА: ${faq.a}`
      : `ЗАДАНИЕ: коротко отреагируй на ответ кандидата и задай РОВНО ОДИН следующий вопрос: "${turn.question}". Больше ничего не добавляй.`
  ].filter(Boolean).join('\n');

  const { reply, by } = await askModelOrLocal([
    { role: 'system', content: `${STAFF_SYSTEM(lang)}\n\nТЕКУЩЕЕ ЗАДАНИЕ:\n${focus}\n\nЗапрещённые темы ещё раз: Discord, VK, Roll20, Foundry, настольные системы, возраст, город, часовой пояс, контакты, гранты.` },
    { role: 'user', content: `ЧЕРНОВАЯ ЗАЯВКА (JSON): ${JSON.stringify({ ...appState, branch: role.key })}` },
    ...history.map(asRole)
  ], () => local(), { temperature: 0.2 });
  return {
    reply: withEnd(reply),
    application: { ...appState, branch: role.key },
    role: role.key,
    done,
    source: by
  };
}



  // A keyless public endpoint, tried only as an optional wording upgrade. Nothing
  // secret is embedded here: the owner's private key never reaches the browser.
  // When it is down - which it often is - the built-in engine above answers.
  var FALLBACK_URL = 'https://text.pollinations.ai/openai';
  var FALLBACK_MODEL = 'openai-fast';
  // Set when the public endpoint fails; see callModel below.
  var freeDownUntil = 0;

  // The public endpoint rejects a "system" role with a 502, but accepts the very same
  // text as a user message. The rules are therefore folded into the first user turn
  // instead of being sent as a separate system message.
  function flattenSystem(messages) {
    var rules = [];
    var rest = [];
    (messages || []).forEach(function (m) {
      if (m && m.role === 'system') rules.push(String(m.content || ''));
      else rest.push(m);
    });
    if (!rules.length) return rest;
    var head = { role: 'user', content: rules.join('\n\n') };
    if (!rest.length) return [head];
    return [head].concat(rest);
  }

  function callModel(messages, options) {
    options = options || {};
    // A dead endpoint must not delay the built-in answer waiting behind it, and a
    // failure opens a short breaker so later messages answer immediately.
    if (Date.now() < freeDownUntil) return Promise.reject(new Error('free model is in cooldown'));
    var payload = {
      model: FALLBACK_MODEL,
      messages: flattenSystem(messages),
      temperature: options.temperature == null ? 0.6 : options.temperature
    };
    var controller = typeof AbortController === 'function' ? new AbortController() : null;
    var timer = controller ? setTimeout(function () { controller.abort(); }, 4000) : null;
    return fetch(FALLBACK_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: controller ? controller.signal : undefined
    }).then(function (res) {
      if (!res.ok) throw new Error('model error ' + res.status);
      return res.json();
    }).then(function (data) {
      var reply = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
      if (!String(reply).trim()) throw new Error('empty model reply');
      return reply;
    }).catch(function (err) {
      freeDownUntil = Date.now() + 5 * 60 * 1000;
      throw err;
    }).finally(function () {
      if (timer) clearTimeout(timer);
    });
  }

  setModelCaller(callModel);

  // Without a server there is no article builder, so a sheet is recognised by its
  // own markers. That is enough to approve and hand off; publishing stays with the
  // owner, which the hand-off text says plainly.
  function sheetKind(messages, application) {
    var text = (Array.isArray(messages) ? messages.map(function (m) { return String(m && m.content || ''); }).join('\n') : '') + '\n' + JSON.stringify(application || {});
    var race = [/самоназвание/i, /особые приметы/i, /уязвимост/i, /форма правления/i, /социальная структура/i];
    var klass = [/роль\s*:/i, /ресурс\s*:/i, /\bHP\s*:/i, /\bХП\s*:/i, /базов\s*урон/i];
    var count = function (list) { return list.filter(function (re) { return re.test(text); }).length; };
    if (count(klass) >= 3) return 'class';
    if (count(race) >= 3) return 'race';
    return null;
  }
  setSheetDetector(sheetKind);

  window.DeeprealmChat = {
    setKnowledge: setKnowledge,
    setSheetDetector: setSheetDetector,
    setEngineArticles: setEngineArticles,
    answerGuide: answerGuide,
    answerInterview: answerInterview,
    answerStaff: answerStaff,
    needsModel: needsModel,
    withEnd: withEnd
  };
})();
